import{_ as e,o as a,c as d,ag as r}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Project Maturity","description":"","frontmatter":{},"headers":[],"relativePath":"reference/concepts/project-maturity.md","filePath":"reference/concepts/project-maturity.md"}'),o={name:"reference/concepts/project-maturity.md"};function i(n,t,s,h,c,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="project-maturity" tabindex="-1">Project Maturity <a class="header-anchor" href="#project-maturity" aria-label="Permalink to &quot;Project Maturity&quot;">​</a></h1><p>VERA judges a project against a ladder. Each step is a gate: it cannot be assessed at one step until every step below it is satisfied.</p><p>The ladder is ordered by <strong>how much VERA can truthfully say</strong> about a project — not by what to do next, which is a separate question the advice on each project page answers.</p><h2 id="the-ladder" tabindex="-1">The ladder <a class="header-anchor" href="#the-ladder" aria-label="Permalink to &quot;The ladder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Name</th><th>Reached when</th><th>What it makes answerable</th></tr></thead><tbody><tr><td>0</td><td>Nominal</td><td>the project exists</td><td>nothing</td></tr><tr><td>1</td><td>Owned</td><td>it has a project manager</td><td>accountability, and it appears in manager comparisons</td></tr><tr><td>2</td><td>Scoped</td><td>it has a deadline and an hours budget, and a contract value if it is fixed price</td><td>&quot;late&quot; and &quot;over&quot; become meaningful; the burn-up, budget health and revenue all have something to measure against</td></tr><tr><td>3</td><td>Staffed</td><td>at least one person has an allocation</td><td>committed capacity, and the allocation reading on the page</td></tr><tr><td>4</td><td>Timed</td><td>every allocation says when its hours sit</td><td>capacity is spread across the weeks the work is actually expected in, rather than the whole life of the project</td></tr><tr><td>5</td><td>Shaped</td><td>allocations carry a week-by-week plan</td><td>pace is judged against the plan the manager drew, rather than an even spread nobody agreed to</td></tr><tr><td>6</td><td>Tracking</td><td>it is on course, within budget health, and will not run out of hours before its deadline</td><td>—</td></tr><tr><td>7</td><td>Profitable</td><td>it is earning at or above the target ratio, with healthy margin and billing in step</td><td>—</td></tr><tr><td>8</td><td>Closed well</td><td>it finished on time and on budget, and the plan it was measured against turned out to be right</td><td>the retrospective verdict</td></tr></tbody></table><p>A project&#39;s step is the highest one for which every step below it is also satisfied. One allocation missing its window drops an otherwise fully planned project back to <strong>Staffed</strong> — deliberately, so the advice points at the window rather than at the shape beyond it.</p><h2 id="recorded-time-is-a-gate-not-a-step" tabindex="-1">Recorded time is a gate, not a step <a class="header-anchor" href="#recorded-time-is-a-gate-not-a-step" aria-label="Permalink to &quot;Recorded time is a gate, not a step&quot;">​</a></h2><p>Time is recorded from the first day, often before anyone has been allocated, so it is not a step of its own. It is a precondition on steps 6 and above: without recorded time those are <strong>unanswerable</strong>, which is not the same as failing. A brand-new project is not behind schedule; nothing is yet known about it.</p><h2 id="not-every-project-should-reach-the-top" tabindex="-1">Not every project should reach the top <a class="header-anchor" href="#not-every-project-should-reach-the-top" aria-label="Permalink to &quot;Not every project should reach the top&quot;">​</a></h2><p>A project&#39;s kind sets how far up the ladder it can meaningfully climb, and stopping at that point means it is configured correctly — not that something is missing.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Stops at</th><th>Why</th></tr></thead><tbody><tr><td>Internal, and all time-off projects</td><td>Owned</td><td>they carry no budget, deadline or allocations by design</td></tr><tr><td>Pro bono</td><td>Tracking</td><td>they earn nothing by definition, so profitability does not apply</td></tr><tr><td>Time and materials, fixed price</td><td>Closed well</td><td>the full ladder applies</td></tr><tr><td>Retainer and agile engagements</td><td>Owned</td><td>the engagement itself holds no period values; each period is assessed in full on its own</td></tr></tbody></table><p>Without these ceilings the advice would nag forever about projects that are set up exactly as intended.</p><h2 id="keeping-this-current" tabindex="-1">Keeping this current <a class="header-anchor" href="#keeping-this-current" aria-label="Permalink to &quot;Keeping this current&quot;">​</a></h2><p>This page is the contract. The advice on each project page cites the step each piece of advice belongs to, and a test checks that every cited step exists here. When VERA gains a new capability it either belongs to a step already on this ladder, or it extends the top — it never quietly reorders the middle.</p>',14)])])}const g=e(o,[["render",i]]);export{u as __pageData,g as default};
